=== too_slow.ino ===
   1| // Debounced toggle: wait for the contacts to settle, then check again
   2| 
   3| bool ledOn = false;
   4| 
   5| void setup() {
   6|   pinMode(2, INPUT_PULLUP);
   7|   pinMode(LED_BUILTIN, OUTPUT);
   8|   digitalWrite(LED_BUILTIN, LOW);
   9|   Serial1.begin(9600);
  10| }
  11| 
  12| void loop() {
  13|   if (digitalRead(2) == LOW) {
  14|     delay(35);                      // let the bounce die out
  15|     if (digitalRead(2) == LOW) {    // still pressed: real press
  16|       ledOn = !ledOn;
  17|       digitalWrite(LED_BUILTIN, ledOn ? HIGH : LOW);
  18|       Serial1.println(ledOn ? "ON" : "OFF");
  19|       while (digitalRead(2) == LOW) {
  20|         // wait for release
  21|       }
  22|     }
  23|   }
  24| }
</student_code>
